CREATE TABLE risk_assessments (id UUID PRIMARY KEY, operation_reference VARCHAR(120) NOT NULL UNIQUE, customer_id UUID NOT NULL, operation_type VARCHAR(50) NOT NULL, amount NUMERIC(19,2) NOT NULL, score INTEGER NOT NULL, decision VARCHAR(10) NOT NULL, triggered_rules TEXT NOT NULL, customer_reason VARCHAR(240) NOT NULL, analyst_explanation TEXT NOT NULL, rule_version VARCHAR(40) NOT NULL, correlation_id UUID NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_risk_assessment_customer_time ON risk_assessments(customer_id, created_at DESC);
CREATE TABLE watchlist_entries (id UUID PRIMARY KEY, subject_type VARCHAR(20) NOT NULL, subject_reference UUID NOT NULL, reason VARCHAR(160) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_by VARCHAR(80) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(subject_type,subject_reference));
CREATE TABLE risk_alerts (id UUID PRIMARY KEY, assessment_id UUID NOT NULL REFERENCES risk_assessments(id), priority VARCHAR(10) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'OPEN', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE fraud_cases (id UUID PRIMARY KEY, alert_id UUID NOT NULL UNIQUE REFERENCES risk_alerts(id), priority VARCHAR(10) NOT NULL, status VARCHAR(30) NOT NULL, assigned_to VARCHAR(80), resolution VARCHAR(40), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), resolved_at TIMESTAMPTZ);
CREATE TABLE case_notes (id UUID PRIMARY KEY, case_id UUID NOT NULL REFERENCES fraud_cases(id), author VARCHAR(80) NOT NULL, note TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE case_evidence (id UUID PRIMARY KEY, case_id UUID NOT NULL REFERENCES fraud_cases(id), evidence_type VARCHAR(40) NOT NULL, reference VARCHAR(160) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE case_status_history (id UUID PRIMARY KEY, case_id UUID NOT NULL REFERENCES fraud_cases(id), previous_status VARCHAR(30), new_status VARCHAR(30) NOT NULL, actor VARCHAR(80) NOT NULL, reason VARCHAR(160), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE risk_audit_history (id UUID PRIMARY KEY, actor VARCHAR(80) NOT NULL, action VARCHAR(80) NOT NULL, target_type VARCHAR(40) NOT NULL, target_id UUID NOT NULL, correlation_id UUID NOT NULL, details VARCHAR(500), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE risk_rule_config (code VARCHAR(60) PRIMARY KEY, enabled BOOLEAN NOT NULL, weight INTEGER NOT NULL, config_value VARCHAR(80) NOT NULL, version VARCHAR(40) NOT NULL, updated_by VARCHAR(80) NOT NULL, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE risk_outbox (id UUID PRIMARY KEY, event_type VARCHAR(80) NOT NULL, aggregate_id UUID NOT NULL, payload TEXT NOT NULL, correlation_id UUID NOT NULL, causation_id UUID, status VARCHAR(20) NOT NULL DEFAULT 'PENDING', attempts INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), published_at TIMESTAMPTZ);
CREATE TABLE processed_events (event_id UUID PRIMARY KEY, processed_at TIMESTAMPTZ NOT NULL DEFAULT now());
